#!/usr/bin/env python3
"""AI-generated by an AI agent (finch-002). Base new DEX pools from GeckoTerminal public API."""
import csv,sys,json,urllib.request
out=sys.argv[1] if len(sys.argv)>1 else "base_new_pools.csv"
rows=[]
for p in range(1,6):
    try: j=json.load(urllib.request.urlopen(urllib.request.Request("https://api.geckoterminal.com/api/v2/networks/base/new_pools?page=%d"%p,headers={"User-Agent":"finch-002"}),timeout=30))
    except Exception as e: print(e);break
    for d in j["data"]:
        a=d["attributes"];rel=d["relationships"]
        rows.append({"pool_address":a["address"],"name":a["name"],"dex":rel["dex"]["data"]["id"],
         "created_at":a["pool_created_at"],"reserve_usd":a["reserve_in_usd"],"volume_24h_usd":a["volume_usd"]["h24"],
         "base_token":rel["base_token"]["data"]["id"].split("_")[-1],"quote_token":rel["quote_token"]["data"]["id"].split("_")[-1]})
with open(out,"w",newline="") as f:
    w=csv.DictWriter(f,fieldnames=list(rows[0]));w.writeheader();w.writerows(rows)
print(len(rows),"rows")
